-- Integration checks use disposable rows and roll back every change.
begin;
create temporary table access_qa(master_id uuid,player_id uuid,observer_id uuid,stranger_id uuid,room_id uuid,invite text);
insert into access_qa(master_id,player_id,observer_id,stranger_id) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant all on access_qa to authenticated;
insert into auth.users(id) select master_id from access_qa union all select player_id from access_qa union all select observer_id from access_qa union all select stranger_id from access_qa;
select set_config('request.jwt.claim.sub',master_id::text,true) from access_qa;
set local role authenticated;
do $$ declare rid uuid;begin rid:=public.create_party_room('QA access','Master');update access_qa set room_id=rid,invite=public.list_party_rooms()->0->>'invite_code';end $$;
reset role;
select set_config('request.jwt.claim.sub',player_id::text,true) from access_qa;
set local role authenticated;
do $$ declare t record;all_summaries jsonb;denied boolean:=false;begin
 select * into t from access_qa;perform public.join_party_room(t.invite,'Player');
 perform public.save_player_book('{"characters":[{"id":"unselected","name":"SECRET UNSELECTED","notes":"HIDDEN_ONE"},{"id":"selected","name":"Shared hero","notes":"PRIVATE CHARACTER NOTES"}],"journal":"PRIVATE BOOK JOURNAL","masterSummaries":[{"id":"selected","name":"Shared hero","hp":10,"passiveInsight":17,"maneuverDC":15,"maneuverAbility":"Ловкость","notes":"LEAK","abilities":[{"key":"dex","score":14,"privateNote":"LEAK"}]}]}'::jsonb,0);
 perform public.set_party_character(t.room_id,'selected');all_summaries:=public.party_character_sheets(t.room_id);
 if all_summaries::text not like '%Shared hero%' or all_summaries::text like '%PRIVATE%' or all_summaries::text like '%LEAK%' or all_summaries::text like '%SECRET%' then raise exception 'FAIL summary allowlist';end if;
 if jsonb_path_query_first(all_summaries,'$[*].characters[*] ? (@.id == "selected")')->>'passiveInsight'<>'17' or jsonb_path_query_first(all_summaries,'$[*].characters[*] ? (@.id == "selected")')->>'maneuverDC'<>'15' then raise exception 'FAIL public character metrics';end if;
 begin perform public.party_character_sheet(t.room_id,t.player_id);exception when others then if sqlerrm='MASTER_REQUIRED' then denied:=true;else raise;end if;end;
 if not denied then raise exception 'FAIL player full sheet access';end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub',observer_id::text,true) from access_qa;
set local role authenticated;
do $$ declare t record;begin select * into t from access_qa;perform public.join_party_room(t.invite,'Observer');if public.party_character_sheets(t.room_id)::text not like '%Shared hero%' then raise exception 'FAIL observer summary';end if;end $$;
reset role;
select set_config('request.jwt.claim.sub',stranger_id::text,true) from access_qa;
set local role authenticated;
do $$ declare t record;denied boolean:=false;begin select * into t from access_qa;begin perform public.party_character_sheets(t.room_id);exception when others then if sqlerrm='NOT_ALLOWED' then denied:=true;else raise;end if;end;if not denied then raise exception 'FAIL outsider summary';end if;end $$;
reset role;
select set_config('request.jwt.claim.sub',master_id::text,true) from access_qa;
set local role authenticated;
do $$ declare t record;full_sheet jsonb;denied boolean:=false;begin
 select * into t from access_qa;full_sheet:=public.party_character_sheet(t.room_id,t.player_id);
 if full_sheet->'character'->>'id'<>'selected' or full_sheet::text not like '%PRIVATE CHARACTER NOTES%' or full_sheet::text like '%PRIVATE BOOK JOURNAL%' or full_sheet::text like '%HIDDEN_ONE%' then raise exception 'FAIL selected full sheet scope';end if;
 begin perform public.party_character_sheet(t.room_id,t.observer_id);exception when others then if sqlerrm='CHARACTER_NOT_FOUND' then denied:=true;else raise;end if;end;if not denied then raise exception 'FAIL empty selection';end if;
 perform public.import_party_monsters(t.room_id,'[{"name":"Pool survives","hpMax":4}]'::jsonb);
 perform public.save_party_combat(t.room_id,'{"name":"Scene","combatants":[],"active":false}'::jsonb,0);
 denied:=false;begin perform public.delete_party_combat(t.room_id,2);exception when others then if sqlerrm='REVISION_CONFLICT' then denied:=true;else raise;end if;end;if not denied then raise exception 'FAIL delete revision guard';end if;
 perform public.delete_party_combat(t.room_id,1);
 if public.party_combat_view(t.room_id) is not null or not exists(select 1 from public.party_monsters where room_id=t.room_id) then raise exception 'FAIL scene deletion or preserved pool';end if;
 perform public.change_party_master(t.room_id,t.observer_id);
 denied:=false;begin perform public.party_character_sheet(t.room_id,t.player_id);exception when others then if sqlerrm='MASTER_REQUIRED' then denied:=true;else raise;end if;end;if not denied then raise exception 'FAIL former master access';end if;
 if public.party_character_sheets(t.room_id)::text not like '%Shared hero%' then raise exception 'FAIL former master shared summary';end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub',observer_id::text,true) from access_qa;
set local role authenticated;
do $$ declare t record;begin select * into t from access_qa;if public.party_character_sheet(t.room_id,t.player_id)->'character'->>'id'<>'selected' then raise exception 'FAIL transferred master';end if;end $$;
reset role;
select set_config('request.jwt.claim.sub',player_id::text,true) from access_qa;
set local role authenticated;
do $$ declare t record;denied boolean:=false;begin select * into t from access_qa;begin perform public.delete_party_combat(t.room_id,0);exception when others then if sqlerrm='MASTER_REQUIRED' then denied:=true;else raise;end if;end;if not denied then raise exception 'FAIL player scene deletion';end if;end $$;
reset role;
rollback;
select 'PASS: shared summaries, master-only selected full sheet, no private book or unselected hero leak, role transfer, revision-checked scene deletion, pool preservation' as result;
